1. using System.Globalization;
2. using RockwellAutomation.FactoryTalkLogixEcho.Api.Client;
3. using RockwellAutomation.FactoryTalkLogixEcho.Api.Interfaces;
4. 
5. namespace Acs.LogixEchoHarness;
6. 
7. /// <summary>
8. /// Owns the emulated chassis and controller for one test run.
9. /// </summary>
10. /// <remarks>
11. /// One of only two files in this repository that bind to a Rockwell SDK. Keeping
12. /// the surface small means an SDK version bump is a contained change.
13. ///
14. /// Teardown order matters: a chassis cannot be deleted while it still holds
15. /// controllers. <see cref="DisposeAsync"/> must run even when a test run throws,
16. /// or the next run collides with a leaked chassis.
17. /// </remarks>
18. public sealed class EchoChassis : IAsyncDisposable
19. {
20.     private readonly IServiceApiClientV2 _service;
21.     private readonly string _name;
22.     private ChassisData? _chassis;
23.     private ControllerData? _controller;
24. 
25.     private EchoChassis(IServiceApiClientV2 service, string name)
26.     {
27.         _service = service;
28.         _name = name;
29.     }
30. 
31.     /// <summary>Comm path for the LDSDK. The prefix routes through the virtual backplane.</summary>
32.     public string CommPath =>
33.         _controller is null
34.             ? throw new InvalidOperationException("controller has not been created")
35.             : @"EmulateEthernet\" + _controller.IPConfigurationData.Address;
36. 
37.     public string ControllerName => _controller?.ControllerName ?? "<none>";
38. 
39.     /// <summary>
40.     /// Download an ACD through the Echo service and wait for the operation to finish.
41.     /// </summary>
42.     /// <remarks>
43.     /// This uses Echo's supported service API rather than the Logix Designer SDK
44.     /// transport, so it isolates Echo project-download failures from FactoryTalk Linx.
45.     /// </remarks>
46.     public async Task DownloadProjectAsync(string acdPath)
47.     {
48.         if (_controller is null)
49.         {
50.             throw new InvalidOperationException("controller has not been created");
51.         }
52. 
53.         Trace($"sending ACD for Echo service download '{acdPath}'");
54.         using var fileHandle = await _service.SendFile(acdPath).ConfigureAwait(false);
55. 
56.         const int maxDownloadStartAttempts = 60;
57.         for (var attempt = 0; ; attempt++)
58.         {
59.             try
60.             {
61.                 Trace($"starting Echo service download attempt {attempt + 1}/{maxDownloadStartAttempts}");
62.                 await _service.Download(_controller.ControllerGuid, fileHandle).ConfigureAwait(false);
63.                 break;
64.             }
65.             catch (ServiceException ex) when (
66.                 attempt < maxDownloadStartAttempts - 1 &&
67.                 ex.Message.Contains(
68.                     "has not yet been synchronized with the requested IP address configuration",
69.                     StringComparison.OrdinalIgnoreCase))
70.             {
71.                 Trace(
72.                     $"controller IP synchronization is still pending on download attempt {attempt + 1}; " +
73.                     "retrying");
74.                 await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
75.             }
76.         }
77. 
78.         const int maxFeedbackAttempts = 120;
79.         for (var attempt = 0; attempt < maxFeedbackAttempts; attempt++)
80.         {
81.             var feedback = await _service.GetDownloadFeedback(_controller.ControllerGuid)
82.                 .ConfigureAwait(false);
83.             Trace(
84.                 $"Echo download state={feedback.State}, progress={feedback.Progress}% " +
85.                 $"({attempt + 1}/{maxFeedbackAttempts})");
86. 
87.             switch (feedback.State)
88.             {
89.                 case OperationState.Done:
90.                     return;
91.                 case OperationState.Failed:
92.                     throw new InvalidOperationException(
93.                         $"Echo service download failed: {string.Join("; ", feedback.Messages)}");
94.                 case OperationState.Canceled:
95.                     throw new InvalidOperationException("Echo service download was canceled");
96.             }
97. 
98.             await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
99.         }
100. 
101.         throw new TimeoutException("Echo service download did not finish within four minutes");
102.     }
103. 
104.     /// <summary>
105.     /// Stand up a chassis and a controller matching the supplied ACD.
106.     /// </summary>
107.     public static async Task<EchoChassis> CreateAsync(string chassisName, string acdPath)
108.     {
109.         if (!File.Exists(acdPath))
110.         {
111.             throw new FileNotFoundException($"ACD not found: {acdPath}", acdPath);
112.         }
113. 
114.         var service = ClientFactory.GetServiceApiClientV2("ACS Logix Harness");
115. 
116.         // The SDK formats messages and parses numbers per the current culture. Pin
117.         // it so a runner with a non-English locale does not change behaviour.
118.         service.Culture = new CultureInfo("en-US");
119. 
120.         var chassis = new EchoChassis(service, chassisName);
121.         try
122.         {
123.             Trace($"starting chassis sweep for '{chassisName}'");
124.             await chassis.SweepExistingAsync().ConfigureAwait(false);
125. 
126.             Trace($"creating chassis '{chassisName}'");
127.             chassis._chassis = await service
128.                 .CreateChassis(new ChassisUpdate
129.                 {
130.                     Name = chassisName,
131.                     Description = "Created by ACS Logix Echo harness"
132.                 })
133.                 .ConfigureAwait(false);
134.             Trace($"created chassis '{chassisName}' ({chassis._chassis.ChassisGuid})");
135. 
136.             Trace($"listing controllers for chassis '{chassisName}'");
137.             var existingControllers = await service
138.                 .ListControllers(chassis._chassis.ChassisGuid)
139.                 .ConfigureAwait(false);
140.             foreach (var existingController in existingControllers)
141.             {
142.                 Trace($"deleting stale controller '{existingController.ControllerName}' ({existingController.ControllerGuid})");
143.                 await service.DeleteController(existingController.ControllerGuid).ConfigureAwait(false);
144.             }
145. 
146.             // Echo reads the controller type, revision and slot out of the ACD
147.             // itself, so the emulated controller always matches the project.
148.             Trace($"sending ACD '{acdPath}'");
149.             var fileHandle = await service.SendFile(acdPath).ConfigureAwait(false);
150.             Trace($"reading controller info from ACD");
151.             var controllerUpdate = await service
152.                 .GetControllerInfoFromAcd(fileHandle)
153.                 .ConfigureAwait(false);
154.             controllerUpdate.ChassisGuid = chassis._chassis.ChassisGuid;
155.             controllerUpdate.Description = "Created by ACS Logix Echo harness";
156.             var controllerNetwork = SelectControllerNetwork(
157.                 await service.ListAvailableEthernetAddresses().ConfigureAwait(false));
158.             controllerUpdate.IPConfigurationData.Address = controllerNetwork.IPAddress;
159.             controllerUpdate.IPConfigurationData.Netmask = controllerNetwork.Netmask;
160.             Trace(
161.                 $"using Echo controller address '{controllerNetwork.IPAddress}' " +
162.                 $"with netmask '{controllerUpdate.IPConfigurationData.Netmask}'");
163. 
164.             const int maxSyncRetries = 60;
165.             for (var attempt = 0; ; attempt++)
166.             {
167.                 try
168.                 {
169.                     Trace($"creating controller attempt {attempt + 1} for '{chassisName}'");
170.                     chassis._controller = await service
171.                         .CreateController(controllerUpdate)
172.                         .ConfigureAwait(false);
173.                     Trace($"created controller '{chassis._controller.ControllerName}' ({chassis._controller.ControllerGuid}) at {chassis._controller.IPConfigurationData.Address}");
174.                     break;
175.                 }
176.                 catch (ServiceException ex) when (
177.                     attempt < maxSyncRetries &&
178.                     ex.Message.Contains(
179.                         "has not yet been synchronized with the requested IP address configuration",
180.                         StringComparison.OrdinalIgnoreCase))
181.                 {
182.                     Trace($"controller IP sync not ready on attempt {attempt + 1}; retrying after delay");
183.                     if (await chassis.TryAdoptExistingControllerAsync(controllerUpdate.Name)
184.                             .ConfigureAwait(false))
185.                     {
186.                         Trace($"adopted existing controller '{chassis._controller!.ControllerName}' ({chassis._controller.ControllerGuid})");
187.                         break;
188.                     }
189. 
190.                     await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
191.                 }
192.                 catch (ServiceException ex) when (
193.                     attempt < maxSyncRetries &&
194.                     ex.Message.Contains("Slot 0 is already occupied.", StringComparison.OrdinalIgnoreCase))
195.                 {
196.                     Trace($"slot 0 occupied on attempt {attempt + 1}; refreshing controller list");
197.                     if (await chassis.TryAdoptExistingControllerAsync(controllerUpdate.Name)
198.                             .ConfigureAwait(false))
199.                     {
200.                         Trace($"adopted existing controller '{chassis._controller!.ControllerName}' ({chassis._controller.ControllerGuid})");
201.                         break;
202.                     }
203. 
204.                     var controllers = await service
205.                         .ListControllers(chassis._chassis.ChassisGuid)
206.                         .ConfigureAwait(false);
207.                     if (!controllers.Any())
208.                     {
209.                         await Task.Delay(TimeSpan.FromSeconds(1)).ConfigureAwait(false);
210.                         continue;
211.                     }
212. 
213.                     foreach (var existingController in controllers)
214.                     {
215.                         await service.DeleteController(existingController.ControllerGuid)
216.                             .ConfigureAwait(false);
217.                     }
218. 
219.                     await Task.Delay(TimeSpan.FromSeconds(1)).ConfigureAwait(false);
220.                 }
221.             }
222. 
223.             Trace("refreshing controller data after creation");
224.             await chassis.RefreshControllerDataAsync().ConfigureAwait(false);
225.             return chassis;
226.         }
227.         catch
228.         {
229.             await chassis.DisposeAsync().ConfigureAwait(false);
230.             throw;
231.         }
232.     }
233. 
234.     /// <summary>
235.     /// Remove a chassis of the same name left behind by a crashed predecessor.
236.     /// </summary>
237.     private async Task SweepExistingAsync()
238.     {
239.         Trace($"listing chassis for sweep of '{_name}'");
240.         var existing = await _service.ListChassis().ConfigureAwait(false);
241.         foreach (var candidate in existing.Where(c =>
242.                      string.Equals(c.Name, _name, StringComparison.OrdinalIgnoreCase)))
243.         {
244.             Trace($"sweeping leaked chassis '{candidate.Name}' ({candidate.ChassisGuid})");
245.             await DeleteChassisAsync(candidate.ChassisGuid).ConfigureAwait(false);
246.         }
247.     }
248. 
249.     private async Task DeleteChassisAsync(Guid chassisGuid)
250.     {
251.         Trace($"listing controllers to delete for chassis {chassisGuid}");
252.         var controllers = await _service.ListControllers(chassisGuid).ConfigureAwait(false);
253.         foreach (var controller in controllers)
254.         {
255.             Trace($"deleting controller '{controller.ControllerName}' ({controller.ControllerGuid})");
256.             await _service.DeleteController(controller.ControllerGuid).ConfigureAwait(false);
257.         }
258. 
259.         Trace($"deleting chassis {chassisGuid}");
260.         await _service.DeleteChassis(chassisGuid).ConfigureAwait(false);
261.     }
262. 
263.     private async Task RefreshControllerDataAsync()
264.     {
265.         if (_controller is null || _chassis is null)
266.         {
267.             return;
268.         }
269. 
270.         const int maxRefreshAttempts = 60;
271.         for (var attempt = 0; attempt < maxRefreshAttempts; attempt++)
272.         {
273.             Trace($"refresh controller data attempt {attempt + 1}/{maxRefreshAttempts}");
274.             var controllers = await _service.ListControllers(_chassis.ChassisGuid).ConfigureAwait(false);
275.             var current = controllers.FirstOrDefault(c => c.ControllerGuid == _controller.ControllerGuid);
276.             if (current is not null)
277.             {
278.                 _controller = current;
279.                 var address = _controller.IPConfigurationData.Address;
280.                 Trace(
281.                     $"controller state: ip={address}, enabled={_controller.IsEnabled}, " +
282.                     $"faulted={_controller.IsFaulted}, error={_controller.ErrorCode}, " +
283.                     $"mode={_controller.ControllerMode}, project={_controller.LoadedProjectName}");
284.                 if (_controller.IsEnabled &&
285.                     !_controller.IsFaulted &&
286.                     _controller.ErrorCode == ControllerStatusErrorCode.ControllerStatusOK)
287.                 {
288.                     return;
289.                 }
290.             }
291. 
292.             await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
293.         }
294. 
295.         throw new TimeoutException(
296.             $"controller '{_controller.ControllerName}' did not reach a ready state in Echo");
297.     }
298. 
299.     private async Task<bool> TryAdoptExistingControllerAsync(string controllerName)
300.     {
301.         if (_chassis is null)
302.         {
303.             return false;
304.         }
305. 
306.         var controllers = await _service.ListControllers(_chassis.ChassisGuid).ConfigureAwait(false);
307.         var current = controllers.FirstOrDefault(c =>
308.             string.Equals(c.ControllerName, controllerName, StringComparison.OrdinalIgnoreCase));
309.         if (current is null)
310.         {
311.             return false;
312.         }
313. 
314.         _controller = current;
315.         return true;
316.     }
317. 
318.     private static EthernetAddressData SelectControllerNetwork(
319.         IEnumerable<EthernetAddressData> availableAddresses)
320.     {
321.         var echoAddresses = availableAddresses
322.             .Where(address => address.IPAddress.AddressFamily ==
323.                               System.Net.Sockets.AddressFamily.InterNetwork)
324.             .ToArray();
325.         var configuredAddress = Environment.GetEnvironmentVariable("ACS_LOGIX_ECHO_IP");
326. 
327.         // Per Rockwell QA64164: loopback addresses (127.x.x.x) cannot be used with Logix Designer.
328.         // Adapter setup with a non-loopback IP is REQUIRED before running tests.
329.         if (string.IsNullOrWhiteSpace(configuredAddress))
330.         {
331.             throw new InvalidOperationException(
332.                 "ACS_LOGIX_ECHO_IP environment variable is not set. This is REQUIRED and must be set " +
333.                 "to a non-loopback IPv4 address (e.g., 192.168.127.5). " +
334.                 "Run: powershell -ExecutionPolicy Bypass -File docs/runbooks/setup-echo-adapter.ps1 " +
335.                 "then restart PowerShell.");
336.         }
337. 
338.         // Validate that the configured address is not loopback (127.x.x.x)
339.         if (configuredAddress.StartsWith("127.", StringComparison.Ordinal))
340.         {
341.             throw new InvalidOperationException(
342.                 $"ACS_LOGIX_ECHO_IP is set to loopback address '{configuredAddress}'. " +
343.                 "Per Rockwell QA64164, loopback addresses cannot be used with Logix Designer. " +
344.                 "Use a non-loopback adapter (e.g., Microsoft Loopback Adapter KM-TEST with 192.168.127.5). " +
345.                 "Run: powershell -ExecutionPolicy Bypass -File docs/runbooks/setup-echo-adapter.ps1");
346.         }
347. 
348.         var configuredNetwork = echoAddresses.FirstOrDefault(address =>
349.             string.Equals(
350.                 address.IPAddress.ToString(),
351.                 configuredAddress,
352.                 StringComparison.Ordinal));
353.         if (configuredNetwork is null)
354.         {
355.             throw new InvalidOperationException(
356.                 $"ACS_LOGIX_ECHO_IP '{configuredAddress}' does not match any Echo-listed IPv4 address. " +
357.                 $"Available addresses: {string.Join(", ", echoAddresses.Select(a => a.IPAddress))}. " +
358.                 "Restart the Echo service after network adapter changes.");
359.         }
360. 
361.         return configuredNetwork;
362.     }
363. 
364.     private static void Trace(string message) =>
365.         Console.WriteLine($"{DateTimeOffset.UtcNow:O} [EchoChassis] {message}");
366. 
367.     public async ValueTask DisposeAsync()
368.     {
369.         if (_chassis is null)
370.         {
371.             return;
372.         }
373. 
374.         try
375.         {
376.             await DeleteChassisAsync(_chassis.ChassisGuid).ConfigureAwait(false);
377.         }
378.         catch (Exception ex)
379.         {
380.             // A failed teardown must not mask the test result that caused it, but
381.             // it does leave a chassis behind - say so loudly enough to be seen in
382.             // the CI log.
383.             Console.Error.WriteLine(
384.                 $"WARNING: could not tear down chassis '{_name}': {ex.Message}");
385.             Console.Error.WriteLine(
386.                 "         Sweep it manually before the next run (see docs/runbooks/troubleshooting.md).");
387.         }
388.         finally
389.         {
390.             _chassis = null;
391.             _controller = null;
392.         }
393.     }
394. }
395.

