 using System.Globalization;
 using RockwellAutomation.FactoryTalkLogixEcho.Api.Client;
 using RockwellAutomation.FactoryTalkLogixEcho.Api.Interfaces;

 namespace Acs.LogixEchoHarness;

 /// <summary>
 /// Owns the emulated chassis and controller for one test run.
 /// </summary>
 /// <remarks>
 /// One of only two files in this repository that bind to a Rockwell SDK. Keeping
 /// the surface small means an SDK version bump is a contained change.
 ///
 /// Teardown order matters: a chassis cannot be deleted while it still holds
 /// controllers. <see cref="DisposeAsync"/> must run even when a test run throws,
 /// or the next run collides with a leaked chassis.
 /// </remarks>
 public sealed class EchoChassis : IAsyncDisposable
 {
     private readonly IServiceApiClientV2 _service;
     private readonly string _name;
     private ChassisData? _chassis;
     private ControllerData? _controller;

     private EchoChassis(IServiceApiClientV2 service, string name)
     {
         _service = service;
         _name = name;
     }

     /// <summary>Comm path for the LDSDK. The prefix routes through the virtual backplane.</summary>
     public string CommPath =>
         _controller is null
             ? throw new InvalidOperationException("controller has not been created")
             : @"EmulateEthernet\" + _controller.IPConfigurationData.Address;

     public string ControllerName => _controller?.ControllerName ?? "<none>";

     /// <summary>
     /// Download an ACD through the Echo service and wait for the operation to finish.
     /// </summary>
     /// <remarks>
     /// This uses Echo's supported service API rather than the Logix Designer SDK
     /// transport, so it isolates Echo project-download failures from FactoryTalk Linx.
     /// </remarks>
     public async Task DownloadProjectAsync(string acdPath)
     {
         if (_controller is null)
         {
             throw new InvalidOperationException("controller has not been created");
         }

         Trace($"sending ACD for Echo service download '{acdPath}'");
         using var fileHandle = await _service.SendFile(acdPath).ConfigureAwait(false);

         const int maxDownloadStartAttempts = 60;
         for (var attempt = 0; ; attempt++)
         {
             try
             {
                 Trace($"starting Echo service download attempt {attempt + 1}/{maxDownloadStartAttempts}");
                 await _service.Download(_controller.ControllerGuid, fileHandle).ConfigureAwait(false);
                 break;
             }
             catch (ServiceException ex) when (
                 attempt < maxDownloadStartAttempts - 1 &&
                 ex.Message.Contains(
                     "has not yet been synchronized with the requested IP address configuration",
                     StringComparison.OrdinalIgnoreCase))
             {
                 Trace(
                     $"controller IP synchronization is still pending on download attempt {attempt + 1}; " +
                     "retrying");
                 await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
             }
         }

         const int maxFeedbackAttempts = 120;
         for (var attempt = 0; attempt < maxFeedbackAttempts; attempt++)
         {
             var feedback = await _service.GetDownloadFeedback(_controller.ControllerGuid)
                 .ConfigureAwait(false);
             Trace(
                 $"Echo download state={feedback.State}, progress={feedback.Progress}% " +
                 $"({attempt + 1}/{maxFeedbackAttempts})");

             switch (feedback.State)
             {
                 case OperationState.Done:
                     return;
                 case OperationState.Failed:
                     throw new InvalidOperationException(
                         $"Echo service download failed: {string.Join("; ", feedback.Messages)}");
                 case OperationState.Canceled:
                     throw new InvalidOperationException("Echo service download was canceled");
             }

             await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
         }

         throw new TimeoutException("Echo service download did not finish within four minutes");
     }

     /// <summary>
     /// Stand up a chassis and a controller matching the supplied ACD.
     /// </summary>
     public static async Task<EchoChassis> CreateAsync(string chassisName, string acdPath)
     {
         if (!File.Exists(acdPath))
         {
             throw new FileNotFoundException($"ACD not found: {acdPath}", acdPath);
         }

         var service = ClientFactory.GetServiceApiClientV2("ACS Logix Harness");

         // The SDK formats messages and parses numbers per the current culture. Pin
         // it so a runner with a non-English locale does not change behaviour.
         service.Culture = new CultureInfo("en-US");

         var chassis = new EchoChassis(service, chassisName);
         try
         {
             Trace($"starting chassis sweep for '{chassisName}'");
             await chassis.SweepExistingAsync().ConfigureAwait(false);

             Trace($"creating chassis '{chassisName}'");
             chassis._chassis = await service
                 .CreateChassis(new ChassisUpdate
                 {
                     Name = chassisName,
                     Description = "Created by ACS Logix Echo harness"
                 })
                 .ConfigureAwait(false);
             Trace($"created chassis '{chassisName}' ({chassis._chassis.ChassisGuid})");

             Trace($"listing controllers for chassis '{chassisName}'");
             var existingControllers = await service
                 .ListControllers(chassis._chassis.ChassisGuid)
                 .ConfigureAwait(false);
             foreach (var existingController in existingControllers)
             {
                 Trace($"deleting stale controller '{existingController.ControllerName}' ({existingController.ControllerGuid})");
                 await service.DeleteController(existingController.ControllerGuid).ConfigureAwait(false);
             }

             // Echo reads the controller type, revision and slot out of the ACD
             // itself, so the emulated controller always matches the project.
             Trace($"sending ACD '{acdPath}'");
             var fileHandle = await service.SendFile(acdPath).ConfigureAwait(false);
             Trace($"reading controller info from ACD");
             var controllerUpdate = await service
                 .GetControllerInfoFromAcd(fileHandle)
                 .ConfigureAwait(false);
             controllerUpdate.ChassisGuid = chassis._chassis.ChassisGuid;
             controllerUpdate.Description = "Created by ACS Logix Echo harness";
             var controllerNetwork = SelectControllerNetwork(
                 await service.ListAvailableEthernetAddresses().ConfigureAwait(false));
             controllerUpdate.IPConfigurationData.Address = controllerNetwork.IPAddress;
             controllerUpdate.IPConfigurationData.Netmask = controllerNetwork.Netmask;
             Trace(
                 $"using Echo controller address '{controllerNetwork.IPAddress}' " +
                 $"with netmask '{controllerUpdate.IPConfigurationData.Netmask}'");

             const int maxSyncRetries = 60;
             for (var attempt = 0; ; attempt++)
             {
                 try
                 {
                     Trace($"creating controller attempt {attempt + 1} for '{chassisName}'");
                     chassis._controller = await service
                         .CreateController(controllerUpdate)
                         .ConfigureAwait(false);
                     Trace($"created controller '{chassis._controller.ControllerName}' ({chassis._controller.ControllerGuid}) at {chassis._controller.IPConfigurationData.Address}");
                     break;
                 }
                 catch (ServiceException ex) when (
                     attempt < maxSyncRetries &&
                     ex.Message.Contains(
                         "has not yet been synchronized with the requested IP address configuration",
                         StringComparison.OrdinalIgnoreCase))
                 {
                     Trace($"controller IP sync not ready on attempt {attempt + 1}; retrying after delay");
                     if (await chassis.TryAdoptExistingControllerAsync(controllerUpdate.Name)
                             .ConfigureAwait(false))
                     {
                         Trace($"adopted existing controller '{chassis._controller!.ControllerName}' ({chassis._controller.ControllerGuid})");
                         break;
                     }

                     await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
                 }
                 catch (ServiceException ex) when (
                     attempt < maxSyncRetries &&
                     ex.Message.Contains("Slot 0 is already occupied.", StringComparison.OrdinalIgnoreCase))
                 {
                     Trace($"slot 0 occupied on attempt {attempt + 1}; refreshing controller list");
                     if (await chassis.TryAdoptExistingControllerAsync(controllerUpdate.Name)
                             .ConfigureAwait(false))
                     {
                         Trace($"adopted existing controller '{chassis._controller!.ControllerName}' ({chassis._controller.ControllerGuid})");
                         break;
                     }

                     var controllers = await service
                         .ListControllers(chassis._chassis.ChassisGuid)
                         .ConfigureAwait(false);
                     if (!controllers.Any())
                     {
                         await Task.Delay(TimeSpan.FromSeconds(1)).ConfigureAwait(false);
                         continue;
                     }

                     foreach (var existingController in controllers)
                     {
                         await service.DeleteController(existingController.ControllerGuid)
                             .ConfigureAwait(false);
                     }

                     await Task.Delay(TimeSpan.FromSeconds(1)).ConfigureAwait(false);
                 }
             }

             Trace("refreshing controller data after creation");
             await chassis.RefreshControllerDataAsync().ConfigureAwait(false);
             return chassis;
         }
         catch
         {
             await chassis.DisposeAsync().ConfigureAwait(false);
             throw;
         }
     }

     /// <summary>
     /// Remove a chassis of the same name left behind by a crashed predecessor.
     /// </summary>
     private async Task SweepExistingAsync()
     {
         Trace($"listing chassis for sweep of '{_name}'");
         var existing = await _service.ListChassis().ConfigureAwait(false);
         foreach (var candidate in existing.Where(c =>
                      string.Equals(c.Name, _name, StringComparison.OrdinalIgnoreCase)))
         {
             Trace($"sweeping leaked chassis '{candidate.Name}' ({candidate.ChassisGuid})");
             await DeleteChassisAsync(candidate.ChassisGuid).ConfigureAwait(false);
         }
     }

     private async Task DeleteChassisAsync(Guid chassisGuid)
     {
         Trace($"listing controllers to delete for chassis {chassisGuid}");
         var controllers = await _service.ListControllers(chassisGuid).ConfigureAwait(false);
         foreach (var controller in controllers)
         {
             Trace($"deleting controller '{controller.ControllerName}' ({controller.ControllerGuid})");
             await _service.DeleteController(controller.ControllerGuid).ConfigureAwait(false);
         }

         Trace($"deleting chassis {chassisGuid}");
         await _service.DeleteChassis(chassisGuid).ConfigureAwait(false);
     }

     private async Task RefreshControllerDataAsync()
     {
         if (_controller is null || _chassis is null)
         {
             return;
         }

         const int maxRefreshAttempts = 60;
         for (var attempt = 0; attempt < maxRefreshAttempts; attempt++)
         {
             Trace($"refresh controller data attempt {attempt + 1}/{maxRefreshAttempts}");
             var controllers = await _service.ListControllers(_chassis.ChassisGuid).ConfigureAwait(false);
             var current = controllers.FirstOrDefault(c => c.ControllerGuid == _controller.ControllerGuid);
             if (current is not null)
             {
                 _controller = current;
                 var address = _controller.IPConfigurationData.Address;
                 Trace(
                     $"controller state: ip={address}, enabled={_controller.IsEnabled}, " +
                     $"faulted={_controller.IsFaulted}, error={_controller.ErrorCode}, " +
                     $"mode={_controller.ControllerMode}, project={_controller.LoadedProjectName}");
                 if (_controller.IsEnabled &&
                     !_controller.IsFaulted &&
                     _controller.ErrorCode == ControllerStatusErrorCode.ControllerStatusOK)
                 {
                     return;
                 }
             }

             await Task.Delay(TimeSpan.FromSeconds(2)).ConfigureAwait(false);
         }

         throw new TimeoutException(
             $"controller '{_controller.ControllerName}' did not reach a ready state in Echo");
     }

     private async Task<bool> TryAdoptExistingControllerAsync(string controllerName)
     {
         if (_chassis is null)
         {
             return false;
         }

         var controllers = await _service.ListControllers(_chassis.ChassisGuid).ConfigureAwait(false);
         var current = controllers.FirstOrDefault(c =>
             string.Equals(c.ControllerName, controllerName, StringComparison.OrdinalIgnoreCase));
         if (current is null)
         {
             return false;
         }

         _controller = current;
         return true;
     }

     private static EthernetAddressData SelectControllerNetwork(
         IEnumerable<EthernetAddressData> availableAddresses)
     {
         var echoAddresses = availableAddresses
             .Where(address => address.IPAddress.AddressFamily ==
                               System.Net.Sockets.AddressFamily.InterNetwork)
             .ToArray();
         var configuredAddress = Environment.GetEnvironmentVariable("ACS_LOGIX_ECHO_IP");

         // Per Rockwell QA64164: loopback addresses (127.x.x.x) cannot be used with Logix Designer.
         // Adapter setup with a non-loopback IP is REQUIRED before running tests.
         if (string.IsNullOrWhiteSpace(configuredAddress))
         {
             throw new InvalidOperationException(
                 "ACS_LOGIX_ECHO_IP environment variable is not set. This is REQUIRED and must be set " +
                 "to a non-loopback IPv4 address (e.g., 192.168.127.5). " +
                 "Run: powershell -ExecutionPolicy Bypass -File docs/runbooks/setup-echo-adapter.ps1 " +
                 "then restart PowerShell.");
         }

         // Validate that the configured address is not loopback (127.x.x.x)
         if (configuredAddress.StartsWith("127.", StringComparison.Ordinal))
         {
             throw new InvalidOperationException(
                 $"ACS_LOGIX_ECHO_IP is set to loopback address '{configuredAddress}'. " +
                 "Per Rockwell QA64164, loopback addresses cannot be used with Logix Designer. " +
                 "Use a non-loopback adapter (e.g., Microsoft Loopback Adapter KM-TEST with 192.168.127.5). " +
                 "Run: powershell -ExecutionPolicy Bypass -File docs/runbooks/setup-echo-adapter.ps1");
         }

         var configuredNetwork = echoAddresses.FirstOrDefault(address =>
             string.Equals(
                 address.IPAddress.ToString(),
                 configuredAddress,
                 StringComparison.Ordinal));
         if (configuredNetwork is null)
         {
             throw new InvalidOperationException(
                 $"ACS_LOGIX_ECHO_IP '{configuredAddress}' does not match any Echo-listed IPv4 address. " +
                 $"Available addresses: {string.Join(", ", echoAddresses.Select(a => a.IPAddress))}. " +
                 "Restart the Echo service after network adapter changes.");
         }

         return configuredNetwork;
     }

     private static void Trace(string message) =>
         Console.WriteLine($"{DateTimeOffset.UtcNow:O} [EchoChassis] {message}");

     public async ValueTask DisposeAsync()
     {
         if (_chassis is null)
         {
             return;
         }

         try
         {
             await DeleteChassisAsync(_chassis.ChassisGuid).ConfigureAwait(false);
         }
         catch (Exception ex)
         {
             // A failed teardown must not mask the test result that caused it, but
             // it does leave a chassis behind - say so loudly enough to be seen in
             // the CI log.
             Console.Error.WriteLine(
                 $"WARNING: could not tear down chassis '{_name}': {ex.Message}");
             Console.Error.WriteLine(
                 "         Sweep it manually before the next run (see docs/runbooks/troubleshooting.md).");
         }
         finally
         {
             _chassis = null;
             _controller = null;
         }
     }
 }

