function Get-NextAvailableIPv4 {
    param([string]$NetworkPrefix, [string[]]$InUse = @())
    for ($h = 2; $h -le 254; $h++) {
        $c = "$NetworkPrefix.$h"
        if ($InUse -notcontains $c) { return $c }
    }
